input.command:
cd /workspace
duckdb -c "
LOAD spatial;
DESCRIBE SELECT * FROM 'data/goias_fields.parquet';
" 
echo "=== q04 rowcount + geom ==="
duckdb -c "
LOAD spatial;
SELECT count(*) n_rows FROM 'data/goias_fields.parquet';
"
echo "=== sample field rows ==="
duckdb -c "
LOAD spatial;
SELECT Id, mode_year, firstyear, firstyearmajority, deforestarea0104,deforestarea0509,deforestarea1014,deforestarea1520,deforestarea2124, hansen_covered_area, hansen_loss_area, mbmode24, mbcov_area_2024, mbvalid_area_2024 FROM 'data/goias_fields.parquet' LIMIT 8;
"

cd /workspace
duckdb -c "
SELECT count(*) rows, count(DISTINCT cod_imovel) distinct_ids FROM read_csv('lists/goias-sample.csv');
DESCRIBE SELECT * FROM read_csv('lists/goias-sample.csv');
SELECT municipio, count(*) FROM read_csv('lists/goias-sample.csv') GROUP BY 1 ORDER BY 2 DESC;
"

cd /workspace
time duckdb data/work.duckdb -c "
LOAD spatial;
CREATE OR REPLACE TABLE parcels AS
  SELECT cod_imovel, num_area, municipio, ST_MakeValid(ST_GeomFromWKB(geom_wkb)) AS geom
  FROM 'data/list_parcels.parquet';
-- overall envelope of listed parcels
CREATE OR REPLACE TABLE env AS
  SELECT ST_MakeEnvelope(min(ST_XMin(geom)),min(ST_YMin(geom)),max(ST_XMax(geom)),max(ST_YMax(geom))) AS g,
         min(ST_XMin(geom)) minx, min(ST_YMin(geom)) miny, max(ST_XMax(geom)) maxx, max(ST_YMax(geom)) maxy
  FROM parcels;
SELECT minx,miny,maxx,maxy FROM env;
"

cd /workspace
printf 'n_fields_in_envelope\n3291\n' > answers/q08.csv
time duckdb data/work.duckdb -c "
LOAD spatial;
-- field areas (planar 4326; ratio cancels CRS)
CREATE OR REPLACE TABLE fa AS SELECT field_id, ST_Area(geom) AS area FROM cand;
-- per (field,parcel) intersection area
CREATE OR REPLACE TABLE fp AS
  SELECT c.field_id, p.cod_imovel, ST_Area(ST_Intersection(c.geom,p.geom)) AS inter_area
  FROM cand c JOIN parcels p ON ST_Intersects(c.geom,p.geom);
-- buffered dissolved union of listed parcels (25 m -> deg)
CREATE OR REPLACE TABLE bufu AS
  SELECT ST_Union_Agg(ST_Buffer(geom, 25.0/111320.0)) AS g FROM parcels;
-- union fraction per candidate field
CREATE OR REPLACE TABLE uf AS
  SELECT c.field_id, ST_Area(ST_Intersection(c.geom, b.g)) AS uinter
  FROM cand c, bufu b;
SELECT count(*) fp_rows FROM fp;
SELECT count(*) uf_rows FROM uf;
"

cd /workspace
duckdb data/work.duckdb -c "
LOAD spatial;
CREATE OR REPLACE TABLE sf AS
  SELECT fp.field_id, fp.cod_imovel, fp.inter_area/fa.area AS frac
  FROM fp JOIN fa USING(field_id);
CREATE OR REPLACE TABLE sfm AS
  SELECT field_id, cod_imovel, frac, max(frac) OVER (PARTITION BY field_id) AS mx FROM sf;
CREATE OR REPLACE TABLE prim AS
  SELECT field_id, cod_imovel FROM (
    SELECT field_id, cod_imovel,
      row_number() OVER (PARTITION BY field_id
        ORDER BY (CASE WHEN frac >= mx - 1e-9 THEN 0 ELSE 1 END), cod_imovel) rn
    FROM sfm
  ) WHERE rn=1;
CREATE OR REPLACE TABLE fmet AS
  SELECT fa.field_id, fa.area,
    COALESCE((SELECT max(frac) FROM sf s WHERE s.field_id=fa.field_id),0.0) AS max_single_frac,
    uf.uinter/fa.area AS union_frac
  FROM fa JOIN uf USING(field_id);
CREATE OR REPLACE TABLE matched AS
  SELECT m.*, (m.max_single_frac >= 0.667) AS by_primary, (m.union_frac >= 0.667) AS by_aggregate,
         p.cod_imovel AS primary_cod
  FROM fmet m LEFT JOIN prim p USING(field_id)
  WHERE m.max_single_frac >= 0.667 OR m.union_frac >= 0.667;
SELECT count(*) matched_fields, sum(CASE WHEN primary_cod IS NULL THEN 1 ELSE 0 END) missing_primary FROM matched;
SELECT sum(CASE WHEN by_primary THEN 1 ELSE 0 END) by_single,
       sum(CASE WHEN NOT by_primary AND by_aggregate THEN 1 ELSE 0 END) by_agg_only FROM matched;
"

cd /workspace
printf 'matched_fields\n793\n' > answers/q09.csv
printf 'by_single_parcel_rule,by_aggregate_rule_only\n766,27\n' > answers/q10.csv
duckdb data/work.duckdb -c "
LOAD spatial;
-- q11
SELECT min(max_single_frac) min_s, avg(max_single_frac) avg_s, avg(union_frac) avg_u FROM matched;
-- q12 excluded: intersect a parcel but not matched
SELECT count(*) n_excluded FROM (SELECT DISTINCT field_id FROM fp) x
  WHERE x.field_id NOT IN (SELECT field_id FROM matched);
-- tie sanity: fields where >=2 parcels within 1e-9 of max
SELECT count(*) tie_fields FROM (
  SELECT field_id, sum(CASE WHEN frac>=mx-1e-9 THEN 1 ELSE 0 END) nt FROM sfm GROUP BY field_id
) WHERE nt>=2 AND field_id IN (SELECT field_id FROM matched);
"

cd /workspace
duckdb data/work.duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT sum(ST_Area_Spheroid(c.geom))/10000.0 AS ha_xy
FROM matched m JOIN cand c USING(field_id);
"
echo "--- compare a single field area both ways ---"
duckdb data/work.duckdb -c "
LOAD spatial;
SELECT ST_Area_Spheroid(geom) def FROM cand LIMIT 1;
SET geometry_always_xy=true;
SELECT ST_Area_Spheroid(geom) xy FROM cand LIMIT 1;
"

cd /workspace
duckdb -c "
LOAD spatial;
SET geometry_always_xy=true;
SELECT Id, ST_Area_Spheroid(geometry) my_m2, hansen_covered_area, mbcov_area_2024
FROM 'data/goias_fields.parquet'
WHERE Id IN (9286787, 9259512, 9262712) ;
"

cd /workspace
duckdb data/work.duckdb -c "
LOAD spatial;
SELECT mbmode24, count(*) n_fields, round(sum(area_ha),2) area_ha,
       round(sum(post2020_loss_ha),4) post2020, round(sum(total_loss_ha),4) totloss,
       sum(CASE WHEN post2020_loss_ha>0 THEN 1 ELSE 0 END) fld_post2020
FROM mf GROUP BY mbmode24 ORDER BY mbmode24;
SELECT sum(CASE WHEN post2020_loss_ha>0 THEN 1 ELSE 0 END) total_fields_post2020 FROM mf;
"

cd /workspace
printf 'n_parcels,n_fields,matched_field_ha,post2020_loss_ha,fields_with_post2020_loss\n117,793,36108.604677398272,114.93037823570098,41\n' > answers/q15.csv
duckdb data/work.duckdb -c "
LOAD spatial;
.mode csv
SELECT '--q17--';
SELECT annex1 AS annex1_commodity, count(*) n_fields, sum(post2020_loss_ha) post2020_loss_ha
FROM mfs WHERE in_scope GROUP BY annex1 ORDER BY annex1;
SELECT '--q18--';
SELECT mbmode24, count(*) n_fields, sum(post2020_loss_ha) post2020_loss_ha
FROM mfs WHERE NOT in_scope GROUP BY mbmode24 ORDER BY mbmode24;
SELECT '--q19--';
SELECT annex1 AS annex1_commodity, sum(area_ha) total_ha,
       sum(CASE WHEN post2020_loss_ha>0 THEN area_ha ELSE 0 END)/sum(area_ha) loss_share
FROM mfs WHERE in_scope GROUP BY annex1 ORDER BY annex1;
"

cd /workspace
duckdb data/work.duckdb <<'SQL'
LOAD spatial;
.mode csv
