cd /workspace
duckdb data/work.duckdb <<'SQL'
LOAD spatial;
SET geometry_always_xy=true;
-- flagged cadasters: any in-scope post2020 loss
CREATE OR REPLACE TABLE flagged AS
SELECT cod_imovel, sum(post2020_loss_ha) post2020_loss_ha
FROM mfs WHERE in_scope GROUP BY cod_imovel HAVING sum(post2020_loss_ha)>0;
SELECT count(*) n_flagged FROM flagged;
-- dominant class (area-weighted) per flagged cadaster, tie -> lower class
CREATE OR REPLACE TABLE domc AS
SELECT cod_imovel, mbmode24 AS dominant_mb FROM (
  SELECT cod_imovel, mbmode24, sum(area_ha) a,
    row_number() OVER (PARTITION BY cod_imovel ORDER BY sum(area_ha) DESC, mbmode24 ASC) rn
  FROM mfs WHERE cod_imovel IN (SELECT cod_imovel FROM flagged)
  GROUP BY cod_imovel, mbmode24
) WHERE rn=1;
SELECT dominant_mb, count(*) FROM domc GROUP BY 1 ORDER BY 1;
-- municipio code from cod_imovel (chars 4-10)
SELECT DISTINCT split_part(cod_imovel,'-',2) AS muni_code, any_value(municipio) FROM parcels GROUP BY 1;
SQL

